using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
namespace Aurora {
public partial class MainWindow {
    void BrowserAutomatic(){
        var card=Card(T("Extensões de segurança nos seus navegadores","Security extensions in your browsers"),T("Os navegadores são detectados ao abrir o OuO. Escolha onde preparar a instalação; as extensões vêm das lojas oficiais.","Browsers are detected when OuO opens. Choose where to prepare installation; extensions come from official stores."));
        BrowserInfo[] found=preview?new BrowserInfo[0]:BrowserInventory.Detect();var choices=new Dictionary<string,CheckBox>();var browsers=new StackPanel();card.Children.Add(browsers);var count=Text("",12,Muted);card.Children.Add(count);
        Action render=()=>{browsers.Children.Clear();choices.Clear();foreach(var browser in found.Where(x=>x.Installed)){var entry=new StackPanel{Margin=new Thickness(0,2,0,8)};bool automatic=!String.IsNullOrEmpty(browser.PolicyPath);var check=Choice(entry,browser.Name+" • "+browser.Scope+" • "+(automatic?T("política automática","automatic policy"):T("instalação assistida","guided installation")),automatic,automatic);choices[browser.Id]=check;var selected=browser;Row(entry,Button(T("uBlock na loja oficial ↗","uBlock in the official store ↗"),()=>OpenExtensionStore(selected,false)),Button(T("WOT na loja oficial ↗","WOT in the official store ↗"),()=>OpenExtensionStore(selected,true)));browsers.Children.Add(entry);}count.Text=found.Count(x=>x.Installed)+T(" navegador(es) encontrado(s)."," browser(s) found.");if(!found.Any(x=>x.Installed))browsers.Children.Add(Text(preview?T("Detecção desativada no modo de verificação.","Detection disabled in verification mode."):T("Nenhum navegador conhecido foi encontrado. Atualize a detecção após instalar um navegador.","No known browser was found. Refresh detection after installing a browser."),13,Muted));};render();pageRefreshActions["browser-extensions"]=()=>{found=BrowserInventory.Detect();render();};
        CheckBox block=Choice(card,T("uBlock Origin no Firefox; uBlock Origin Lite nos Chromium","uBlock Origin on Firefox; uBlock Origin Lite on Chromium"),true,true),wot=Choice(card,T("WOT Web of Trust (opcional)","WOT Web of Trust (optional)"),true,false),protect=Choice(card,T("Solicitar proteção contra remoção onde houver suporte","Request removal protection where supported"),true,false);
        Note(card,"WOT solicita acesso amplo à navegação. Revise as permissões antes de escolher. As políticas podem indicar navegador gerenciado e uma política da organização pode prevalecer. Novos navegadores/canais continuam em fase de testes; Opera/GX, Vivaldi e LibreWolf usam a loja assistida nesta versão.","WOT requests broad browsing access. Review permissions before choosing it. Policies can indicate a managed browser and an organization policy may prevail. New browsers/channels remain in testing; Opera/GX, Vivaldi and LibreWolf use guided store installation in this version.");
        TextBox report=Input("");report.IsReadOnly=true;report.AcceptsReturn=true;report.Height=170;report.TextWrapping=TextWrapping.Wrap;report.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;
        Row(card,Button(T("Atualizar navegadores detectados","Refresh detected browsers"),()=>{if(preview)return;BrowserInfo[] refreshed=null;Work(T("Checar navegadores instalados","Check installed browsers"),()=>{refreshed=BrowserInventory.Detect(true);return "OK";},r=>{if(refreshed==null){report.Text=r;return;}found=refreshed;render();});}),Button(T("Preparar instalação automática","Set up automatic installation"),()=>{bool u=block.IsChecked==true,w=wot.IsChecked==true,locked=protect.IsChecked==true;BrowserInfo[] selected=found.Where(x=>choices.ContainsKey(x.Id)&&choices[x.Id].IsChecked==true).GroupBy(x=>x.PolicyPath,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToArray();if(!u&&!w||selected.Length==0){ShowNotice(T("Selecione uma extensão e um navegador com política automática.","Select an extension and a browser with automatic policy support."));return;}if(!Confirm(T("Preparar instalação em: ","Set up installation in: ")+String.Join(", ",selected.Select(x=>x.Name))+"\n"+(u?"uBlock Origin / Lite\n":"")+(w?"WOT Web of Trust\n":"")+T("O navegador busca as extensões na loja ao atualizar suas políticas. WOT pode acessar páginas visitadas. A regra aplicada não confirma que o navegador já concluiu a instalação.","The browser fetches extensions from the store when policies refresh. WOT may access visited pages. An applied rule does not confirm that the browser completed installation.")))return;Work("Browser extensions",()=>BrowserExtensions.Apply(selected,u,w,new WindowsRegistryStore(),journal,locked),r=>report.Text=r);}),Button(T("Privacidade do WOT","WOT privacy"),()=>Open("https://www.mywot.com/en/privacy/privacy_policy")));AttachResult(card,report);
    }
}
}
